119	/* ---- WorkOS: the device flow and the renewal -------------------------------- */
120	
121	const WORKOS = "https://api.workos.com";
122	
123	/** What a token endpoint answers: tokens on success, an `error` code otherwise. */
124	interface TokenAnswer {
125	  access_token?: string;
126	  refresh_token?: string;
127	  error?: string;
128	  error_description?: string;
129	}
130	
131	/** The bits of the world the flow touches, so a test can hand in its own. */
132	export interface FlowDeps {
133	  fetch: typeof fetch;
134	  sleep: (ms: number) => Promise<void>;
135	  say: (line: string) => void;
136	  /** Try to open a URL in a browser; a failure is quiet, the code is on screen anyway. */
137	  open: (url: string) => void;
138	  now: () => number;
139	}
140	
141	const realDeps: FlowDeps = {
142	  fetch: (input, init) => fetch(input, init),
143	  sleep: (ms) => new Promise((r) => setTimeout(r, ms)),
144	  say: (line) => console.log(line),
145	  open: (url) => {
146	    try {
147	      const [cmd, args] =
148	        process.platform === "win32"
149	          ? ["cmd", ["/c", "start", "", url]]
150	          : process.platform === "darwin"
151	            ? ["open", [url]]
152	            : ["xdg-open", [url]];
153	      spawn(cmd, args, { detached: true, stdio: "ignore" })
154	        .on("error", () => {})
155	        .unref();
156	    } catch {
157	      /* no browser here; the link is printed */
158	    }
159	  },
160	  now: () => Date.now(),
161	};
162	
163	async function postForm(
164	  deps: FlowDeps,
165	  url: string,
166	  form: Record<string, string>,
167	): Promise<{ status: number; body: Record<string, unknown> }> {
168	  const response = await deps.fetch(url, {
169	    method: "POST",
170	    headers: { "content-type": "application/x-www-form-urlencoded", accept: "application/json" },
171	    body: new URLSearchParams(form).toString(),
172	  });
173	  const text = await response.text();
174	  try {
175	    return { status: response.status, body: JSON.parse(text) as Record<string, unknown> };
176	  } catch {
177	    throw new Error(`WorkOS did not answer as expected (${response.status})`);
178	  }
179	}
180	
181	/** When a JWT says it stops working, or a fallback if it does not say. */
182	function expiryOf(accessToken: string, now: number): string {
183	  try {
184	    const payload = JSON.parse(Buffer.from(accessToken.split(".")[1] ?? "", "base64url").toString("utf8")) as { exp?: number };
185	    if (typeof payload.exp === "number") return new Date(payload.exp * 1000).toISOString();
186	  } catch {
187	    /* not a JWT we can read; assume WorkOS's shortest lifetime */
188	  }
189	  return new Date(now + 5 * 60_000).toISOString();
190	}
191	
192	/**
193	 * The device flow, start to finish: ask for a code, show it, poll until the
194	 * person confirms it in a browser or the code dies. Returns the session.
195	 */
196	export async function deviceFlow(clientId: string, issuer: string, deps: FlowDeps = realDeps): Promise<Session> {
197	  const start = await postForm(deps, `${issuer}/user_management/authorize/device`, { client_id: clientId });
198	  const s = start.body as {
199	    device_code?: string;
200	    user_code?: string;
201	    verification_uri?: string;
202	    verification_uri_complete?: string;
203	    expires_in?: number;
204	    interval?: number;
205	    error_description?: string;
206	  };
207	  if (start.status >= 400 || !s.device_code || !s.user_code || !s.verification_uri) {
208	    throw new Error(s.error_description ?? `WorkOS would not start a sign-in (${start.status})`);
209	  }
210	  deps.say("");
211	  deps.say(`  Open  ${s.verification_uri}`);
212	  deps.say(`  Code  ${s.user_code}`);
213	  deps.say("");
214	  deps.say("Waiting for you to confirm it there. Ctrl-C gives up.");
215	  if (s.verification_uri_complete) deps.open(s.verification_uri_complete);
216	
217	  let interval = Math.max(1, s.interval ?? 5);
218	  const deadline = deps.now() + (s.expires_in ?? 300) * 1000;
219	  while (deps.now() < deadline) {
220	    await deps.sleep(interval * 1000);
221	    const poll = await postForm(deps, `${issuer}/user_management/authenticate`, {
222	      grant_type: DEVICE_GRANT,
223	      device_code: s.device_code,
224	      client_id: clientId,
225	    });
226	    const a = poll.body as TokenAnswer;
227	    if (a.access_token && a.refresh_token) {
228	      return {
229	        clientId,
230	        issuer,
231	        accessToken: a.access_token,
232	        refreshToken: a.refresh_token,
233	        expiresAt: expiryOf(a.access_token, deps.now()),
234	      };
235	    }
236	    switch (a.error) {
237	      case "authorization_pending":
238	        continue;
239	      case "slow_down":
240	        interval += 1;
241	        continue;
242	      case "access_denied":
243	        throw new Error("the sign-in was refused in the browser");
244	      case "expired_token":
245	        throw new Error("the code expired before it was confirmed; run `runlog login` again");
246	      default:
247	        throw new Error(a.error_description ?? a.error ?? `WorkOS answered ${poll.status}`);
248	    }
249	  }
250	  throw new Error("the code expired before it was confirmed; run `runlog login` again");
251	}
252	
253	/** A new access token from the refresh token; the refresh token rotates too. */
254	export async function renew(session: Session, deps: FlowDeps = realDeps): Promise<Session> {
255	  const answer = await postForm(deps, `${session.issuer}/user_management/authenticate`, {
256	    grant_type: "refresh_token",
257	    refresh_token: session.refreshToken,
258	    client_id: session.clientId,
259	  });
260	  const a = answer.body as TokenAnswer;
261	  if (!a.access_token || !a.refresh_token) {
262	    throw new Error("your sign-in has lapsed; run `runlog login` again");
263	  }
264	  return { ...session, accessToken: a.access_token, refreshToken: a.refresh_token, expiresAt: expiryOf(a.access_token, deps.now()) };
265	}
266	
267	/* ---- the API, as whoever is signed in ---------------------------------------- */
268	
269	/**
270	 * The bearer to send: the key, or the session's access token, renewed first
271	 * when it is about to lapse. `force` renews regardless, after a 401.
272	 */
273	export async function bearer(creds: Credentials, force = false, deps: FlowDeps = realDeps): Promise<string> {
274	  if (creds.key) return creds.key;
275	  if (!creds.session) throw new Error("not signed in: run `runlog login`");
276	  const lapsing = !creds.session.expiresAt || Date.parse(creds.session.expiresAt) - deps.now() < RENEW_MARGIN_MS;
277	  if (!force && !lapsing) return creds.session.accessToken;
278	  const session = await renew(creds.session, deps);
279	  creds.session = session;
280	  if (!process.env["RUNLOG_API_KEY"]) save(creds);
281	  return session.accessToken;
282	}
283	
284	/** One call to the API as whoever is signed in. Throws with the API's own words on a failure. */
285	export async function api<T>(method: string, path: string, body?: unknown): Promise<T> {
286	  const creds = credentials();
287	  if (!creds) throw new Error("not signed in: run `runlog login`");
288	  const once = async (token: string) => {
289	    const response = await fetch(`${creds.api.replace(/\/$/, "")}${path}`, {
290	      method,
291	      headers: { authorization: `Bearer ${token}`, ...(body !== undefined ? { "content-type": "application/json" } : {}) },
292	      ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
293	    });
294	    const text = await response.text();

