123	/**
124	 * The bearer to send: the key, or the session's access token, renewed first
125	 * when it is about to lapse. `force` renews regardless, after a 401.
126	 */
127	export async function bearer(creds: Credentials, force = false, deps: FlowDeps = realDeps): Promise<string> {
128	  if (creds.key) return creds.key;
129	  if (!creds.session) throw new Error("not signed in: run `runlog login`");
130	  const lapsing = !creds.session.expiresAt || needsRenewal(creds.session, deps.now());
131	  if (!force && !lapsing) return creds.session.accessToken;
132	  const session = await renew(creds.session, deps);
133	  creds.session = session;
134	  if (!process.env["RUNLOG_API_KEY"]) save(creds);
135	  return session.accessToken;
136	}
