138	/** One call to the API as whoever is signed in. Throws with the API's own words on a failure. */
139	export async function api<T>(method: string, path: string, body?: unknown): Promise<T> {
140	  const creds = credentials();
141	  if (!creds) throw new Error("not signed in: run `runlog login`");
142	  const once = async (token: string) => {
143	    const response = await fetch(`${creds.api.replace(/\/$/, "")}${path}`, {
144	      method,
145	      headers: { authorization: `Bearer ${token}`, ...(body !== undefined ? { "content-type": "application/json" } : {}) },
146	      ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
147	    });
148	    const text = await response.text();
149	    let parsed: unknown = null;
150	    try {
151	      parsed = JSON.parse(text);
152	    } catch {
153	      throw new Error(`the API at ${creds.api} did not answer as expected (${response.status})`);
154	    }
155	    return { status: response.status, parsed };
156	  };
157	  let answer = await once(await bearer(creds));
158	  // A session's token can be refused between the expiry check and the call;
159	  // renew once and try again before deciding the sign-in is gone.
160	  if (answer.status === 401 && creds.session) answer = await once(await bearer(creds, true));
161	  if (answer.status === 401) {
162	    throw new Error(
163	      creds.key
164	        ? "that key is not accepted; make a new one on your profile page and `runlog login --key` again"
165	        : "your sign-in has lapsed; run `runlog login` again",
166	    );
167	  }
168	  if (answer.status >= 400) {
169	    const said = (answer.parsed as { error?: string } | null)?.error;
170	    throw new Error(said ?? `the API said ${answer.status}`);
171	  }
172	  return answer.parsed as T;
173	}
