183	export async function cmdLogin(args: string[], deps: FlowDeps = realDeps): Promise<number> {
184	  const apiUrl = (flag(args, "--api") ?? process.env["RUNLOG_API"] ?? DEFAULT_API).replace(/\/$/, "");
185	  if (process.env["RUNLOG_API_KEY"]) {
186	    console.error("RUNLOG_API_KEY is set, so that is what every command will use; unset it to sign in as yourself");
187	    return 1;
188	  }
189	
190	  if (args.includes("--key")) {
191	    console.log("Paste a command-line key from your profile page in Runlog. It is not shown as you type.");
192	    const key = await ask("key: ", true);
193	    if (!key.startsWith("rl_")) {
194	      console.error("that does not look like a Runlog key; they begin with rl_");
195	      return 1;
196	    }
197	    // Prove it before keeping it, so a typo is caught here and not on the next command.
198	    save({ api: apiUrl, key, savedAt: new Date().toISOString() });
199	    try {
200	      await greet(apiUrl);
201	      return 0;
202	    } catch (error) {
203	      unlinkSync(credentialsPath());
204	      console.error(error instanceof Error ? error.message : String(error));
205	      return 1;
206	    }
207	  }
208	
209	  try {
210	    // Which WorkOS application to sign in against is the API's to say.
211	    const response = await deps.fetch(`${apiUrl}/auth/cli`, { headers: { accept: "application/json" } });
212	    const text = await response.text();
213	    let about: { clientId?: string | null; issuer?: string } = {};
214	    try {
215	      about = JSON.parse(text) as typeof about;
216	    } catch {
217	      throw new Error(`the API at ${apiUrl} did not answer as expected (${response.status})`);
218	    }
219	    if (!about.clientId)
220	      throw new Error(`the API at ${apiUrl} cannot sign in a terminal yet; use \`runlog login --key\` with a key from your profile page`);
221	    const session = await deviceFlow(about.clientId, about.issuer ?? WORKOS, deps);
222	    save({ api: apiUrl, session, savedAt: new Date().toISOString() });
223	    await greet(apiUrl);
224	    return 0;
225	  } catch (error) {
226	    console.error(error instanceof Error ? error.message : String(error));
227	    return 1;
228	  }
229	}
