266	interface StoredKey {
267	  publicKey: string;
268	  privateKey: string;
269	  fingerprint: string;
270	}
271	
272	function readKey(path: string): StoredKey {
273	  const key = JSON.parse(readFileSync(resolve(path), "utf8")) as Partial<StoredKey>;
274	  if (!key.privateKey || !key.publicKey) throw new Error(`${path} is not a runlog signing key`);
275	  return { publicKey: key.publicKey, privateKey: key.privateKey, fingerprint: key.fingerprint ?? "" };
276	}
