278	export async function cmdClaim(args: string[]): Promise<number> {
279	  const keyPath = args.filter((a) => !a.startsWith("-"))[0];
280	  if (!keyPath) {
281	    console.error("usage: runlog claim key.json");
282	    return 2;
283	  }
284	  try {
285	    const key = readKey(keyPath);
