392	    if (!listing.ok) throw new Error(listing.error);
393	    const { pack, payload } = listing;
394	
395	    const me = await api<{ publisher: { name: string } | null }>("GET", "/publishers/me");
396	    if (!me.publisher) throw new Error("this account is not a publisher; become one on your profile page first");
397	
398	    const id = encodeURIComponent(pack.id);
399	    const put = await api<{ pack: { status: string; price: { amount: number; currency: string } | null } }>(
400	      "PUT",
401	      `/publishers/packs/${id}`,
402	      payload,
403	    );
404	    const dollars = (p: { amount: number; currency: string }) => `${p.currency.toUpperCase()} ${(p.amount / 100).toFixed(2)}`;
405	    console.log(`uploaded ${pack.id} v${pack.version} to ${me.publisher.name}`);
406	
407	    if (args.includes("--draft")) {
408	      console.log(
409	        put.pack.status === "listed"
410	          ? "  still listed; the card follows the new version"
411	          : "  kept as a draft; list it with --price or --free",
412	      );
413	      return 0;
414	    }
415	    if (price === "keep") {
416	      if (put.pack.status === "listed") console.log(`  listed ${put.pack.price ? `at ${dollars(put.pack.price)}` : "free"}, as before`);
417	      else console.log("  not listed yet; pass --price 3.00 or --free to put it in the marketplace");
418	      return 0;
419	    }
420	    const listed = await api<{ available?: boolean; error?: string; listing?: { price: "free" | { amount: number; currency: string } } }>(
421	      "POST",
422	      `/publishers/packs/${id}/listing`,
423	      price === "free" ? {} : price,
424	    );
425	    if (listed.available === false) throw new Error(listed.error ?? "selling is not switched on here yet; a free listing works");
426	    const shown = listed.listing?.price;
427	    console.log(`  listed ${shown && shown !== "free" ? `at ${dollars(shown)}` : "free"}`);
428	    return 0;
429	  } catch (error) {
430	    console.error(error instanceof Error ? error.message : String(error));
431	    return 1;
432	  }
433	}
